package export_ohrats_rc_artifact_cache_cache

import (
	"crypto/sha256"
	"fmt"
	"math"

	witTypes "go.bytecodealliance.org/pkg/wit/types"
	"wit_component/ohrats_rc_artifact_cache_local_storage"
	"wit_component/ohrats_rc_artifact_cache_types"
)

const maxArtifactBytes = 48 * 1024 * 1024

type fetchResult = witTypes.Result[witTypes.Option[ohrats_rc_artifact_cache_types.Artifact], string]

func Fetch(providerKey string, request ohrats_rc_artifact_cache_types.FetchRequest) fetchResult {
	if providerKey != "local" {
		return witTypes.Err[witTypes.Option[ohrats_rc_artifact_cache_types.Artifact], string](
			fmt.Sprintf("local cache does not handle %q", providerKey),
		)
	}
	if err := validateRequest(request); err != "" {
		return witTypes.Err[witTypes.Option[ohrats_rc_artifact_cache_types.Artifact], string](err)
	}
	read := ohrats_rc_artifact_cache_local_storage.Read(request.Digest, request.MaxBytes)
	if read.IsErr() {
		return witTypes.Err[witTypes.Option[ohrats_rc_artifact_cache_types.Artifact], string](read.Err())
	}
	artifact := read.Ok()
	if artifact.IsNone() {
		return witTypes.Ok[witTypes.Option[ohrats_rc_artifact_cache_types.Artifact], string](
			witTypes.None[ohrats_rc_artifact_cache_types.Artifact](),
		)
	}
	value := artifact.Some()
	if err := validateArtifact(request, value); err != "" {
		return witTypes.Err[witTypes.Option[ohrats_rc_artifact_cache_types.Artifact], string](err)
	}
	return witTypes.Ok[witTypes.Option[ohrats_rc_artifact_cache_types.Artifact], string](
		witTypes.Some(value),
	)
}

func validateRequest(request ohrats_rc_artifact_cache_types.FetchRequest) string {
	if !validDigest(request.Digest) {
		return fmt.Sprintf("invalid artifact digest %q", request.Digest)
	}
	if request.MaxBytes > math.MaxUint32 {
		return "artifact capacity exceeds host limits"
	}
	maximum := uint64(request.MaxBytes)
	if maximum == 0 || maximum > maxArtifactBytes {
		return "artifact capacity must be between 1 and 48 MiB"
	}
	return ""
}

func validateArtifact(request ohrats_rc_artifact_cache_types.FetchRequest, artifact ohrats_rc_artifact_cache_types.Artifact) string {
	if artifact.Digest != request.Digest {
		return "local cache returned an address mismatch"
	}
	if uint64(len(artifact.Bytes)) > request.MaxBytes || len(artifact.Bytes) > maxArtifactBytes {
		return "local cache artifact exceeds requested capacity"
	}
	actual := fmt.Sprintf("sha256:%x", sha256.Sum256(artifact.Bytes))
	if actual != artifact.Digest {
		return "local cache artifact failed digest verification"
	}
	return ""
}

func validDigest(value string) bool {
	const prefix = "sha256:"
	if len(value) != len(prefix)+64 || value[:len(prefix)] != prefix {
		return false
	}
	for _, char := range []byte(value[len(prefix):]) {
		if char >= '0' && char <= '9' {
			continue
		}
		if char < 'a' || char > 'f' {
			return false
		}
	}
	return true
}
